-- Preserve the content editors' wording when fixing verified legacy table blocks.
-- Exact source matches make reruns safe and guard any subsequently edited body.
-- Search titles and opening answers use the observed UK siblings and Australian teacher-selection intents.

update public.pages
set body_html = replace(replace(replace(body_html, '<p><strong>Course</strong></p><p><strong>Learning Objective</strong></p><p>Noorani Qaida</p><p>Arabic letters and basic reading</p><p>Quran Nazara</p><p>Quran reading fluency</p><p>Quran with Tajweed</p><p>Correct recitation</p><p>Quran Hifz</p><p>Memorization and revision</p>', '<table><caption>Online Quran course options for Houston</caption><thead><tr><th scope="col">Course</th><th scope="col">Learning objective</th></tr></thead><tbody><tr><th scope="row">Noorani Qaida</th><td>Arabic letters and basic reading</td></tr><tr><th scope="row">Quran Nazara</th><td>Quran reading fluency</td></tr><tr><th scope="row">Quran with Tajweed</th><td>Correct recitation</td></tr><tr><th scope="row">Quran Hifz</th><td>Memorization and revision</td></tr></tbody></table>'), '<p><strong>Time Zone</strong></p><p><strong>UTC Offset</strong></p><p>Houston CST</p><p>UTC−6</p><p>Houston CDT</p><p>UTC−5</p><p>Pakistan PKT</p><p>UTC+5</p>', '<table><caption>Houston lesson scheduling and UTC offsets</caption><thead><tr><th scope="col">Time zone</th><th scope="col">UTC offset</th></tr></thead><tbody><tr><th scope="row">Houston CST</th><td>UTC−6</td></tr><tr><th scope="row">Houston CDT</th><td>UTC−5</td></tr><tr><th scope="row">Pakistan PKT</th><td>UTC+5</td></tr></tbody></table>'), '<h2>Online Quran Classes in Houston, United States</h2><p></p><p>Muslim families in Houston often look for reliable Quran education that helps children and adults improve Arabic reading, Quran recitation, Tajweed and memorization. Parents want their children to learn the Quran alongside school education, while adults may want to begin Quran reading or improve their existing recitation skills.</p>', '<p>Houston families can take live one-to-one Quran classes from home in Central Time. Start with <a href="/courses/noorani-qaida">Noorani Qaida</a> for Arabic letters, <a href="/courses/tajweed">Tajweed practice</a> for feedback on recitation or <a href="/courses/hifz-quran">Hifz</a> for memorisation and revision. Give Admissions a lesson date and your preferred Houston time when you request a trial.</p>'),
    updated_at = now()
where slug = 'locations-united-states-houston' and locale = 'en' and status = 'published' and deleted_at is null
  and (strpos(body_html, '<p><strong>Course</strong></p><p><strong>Learning Objective</strong></p><p>Noorani Qaida</p><p>Arabic letters and basic reading</p><p>Quran Nazara</p><p>Quran reading fluency</p><p>Quran with Tajweed</p><p>Correct recitation</p><p>Quran Hifz</p><p>Memorization and revision</p>') > 0
     or strpos(body_html, '<p><strong>Time Zone</strong></p><p><strong>UTC Offset</strong></p><p>Houston CST</p><p>UTC−6</p><p>Houston CDT</p><p>UTC−5</p><p>Pakistan PKT</p><p>UTC+5</p>') > 0
     or strpos(body_html, '<h2>Online Quran Classes in Houston, United States</h2><p></p><p>Muslim families in Houston often look for reliable Quran education that helps children and adults improve Arabic reading, Quran recitation, Tajweed and memorization. Parents want their children to learn the Quran alongside school education, while adults may want to begin Quran reading or improve their existing recitation skills.</p>') > 0);

