where slug = 'locations-australia' and locale = 'en' and status = 'published' and deleted_at is null
  and (strpos(body_html, '<p>Australian cityStandard timeDaylight savingSydneyAEST (UTC+10)AEDT (UTC+11)MelbourneAEST (UTC+10)AEDT (UTC+11)BrisbaneAEST (UTC+10)Not observedAdelaideACST (UTC+9:30)ACDT (UTC+10:30)PerthAWST (UTC+8)Not observed</p>') > 0);

update public.blog_posts
set body_html = replace(body_html, '<p>Quran lessons for multiple children require individual learning assessments, suitable lesson schedules, and clear package arrangements for every learner. Although siblings share the same household, they may have different Quran reading abilities, learning speeds, ages, and educational needs.</p>', '<p><strong>Yes. Siblings can take online Quran classes with the same academy and learn at their own levels.</strong> Send a separate trial request for each child using a parent’s contact details. If they share a device, give Admissions two non-overlapping lesson times around school and leave a short gap to switch materials. Ask for the lesson length and fee for each learner.</p>'),
    updated_at = now()
where slug = 'family-quran-learning-multiple-children' and locale = 'en' and status = 'published' and deleted_at is null
  and starts_with(body_html, '<p>Quran lessons for multiple children require individual learning assessments, suitable lesson schedules, and clear package arrangements for every learner. Although siblings share the same household, they may have different Quran reading abilities, learning speeds, ages, and educational needs.</p>');

update public.blog_posts
set title = 'How to Choose an Online Quran Teacher in Australia',
    seo_title = 'Online Quran Teacher in Australia',
    seo_description = 'Compare online Quran teachers in Australia for children and adults. Know what to ask about recitation feedback, local lesson times and trial classes.',
    cover_url = coalesce(nullif(cover_url, ''), '/images/learning/online-lesson-female-v4-1200.webp'),
    cover_alt = case when coalesce(cover_url, '') = '' then 'Illustrative scene of a girl following her lesson at home with a female Quran teacher on a laptop video call' else cover_alt end,
    updated_at = now()
where slug = 'quran-teacher-online-in-australia' and locale = 'en' and status = 'published' and deleted_at is null
  and title = 'Quran Teacher Online in Australia | Live 1-to-1 Quran Classes' and seo_title = 'Quran Teacher Online in Australia | Live 1-to-1 Quran Classes';
